        raw = self.headers.get("Content-Length")
        if raw is None:
            return b""
        raw = raw.strip()
        if not re.fullmatch(r"[0-9]+", raw):
            raise _Answer(400, "invalid Content-Length %r" % raw)
        n = int(raw)
        if n > MAX_BODY:
            if n <= _DRAIN_LIMIT:
                self._drain(n)
            raise _Answer(413, "request body too large: %d bytes, at most %d" % (n, MAX_BODY))
        data = b""
        while len(data) < n:
            chunk = self.rfile.read(n - len(data))
            if not chunk:
                break
            data += chunk
        return data

    # -------------------------------------------------------------- dispatch
    def _dispatch(self):
        try:
            response = self._handle()
        except _Answer as a:
            self._send_error_json(a.status, a.message, a.headers)
            return
        except TallybookError as e:
            self._send_error_json(_STATUS.get(e.code, 400), e.message or e.code)
            return
        except Exception as e:  # anything unexpected: a 500, nothing printed
            self._send_error_json(500, "internal error: %s" % (str(e) or type(e).__name__))
            return
        self._send(response.status, response.body, response.ctype)

    def _handle(self):
        verb = self.command
        pieces, query = _split_path(self.path)
        found = _route(pieces) if pieces is not None else None
        if found is None:
            self._read_body_quietly()
            raise _Answer(404, "no such path: %s" % self.path.split("?", 1)[0].split("#", 1)[0])
        verbs, name, captured, pieces = found
        if verb not in verbs:
            self._read_body_quietly()
            raise _Answer(405, "method %s not allowed here" % verb, [("Allow", ", ".join(sorted(verbs)))])
        data = self._read_body()
        body = None
        if verb in ("POST", "PUT"):
            ctype = _content_type(self.headers.get("Content-Type"))
            if name == "import":
                if not data:
                    body = ""
                elif ctype in ("text/csv", "text/plain"):
                    body = self._decode(data)
                elif ctype == "application/json":
                    body = self._parse_json(data)
                else:
                    raise _Answer(415, "unsupported content type %s: send application/json, text/csv or "
                                       "text/plain" % (ctype or "(none)"))
            else:
                if data and ctype != "application/json":
                    raise _Answer(415, "unsupported content type %s: send application/json" % (ctype or "(none)"))
                body = self._parse_json(data) if data else {}
        app = self.app
        method = getattr(app, "import_" if name == "import" else name)
        store = Store.open(app.db_path)
        try:
            return method(store, verb, captured, pieces, query, body)
        finally:
            store.close()

    def _read_body_quietly(self):
        try:
            self._read_body()
        except _Answer:
            pass

    @staticmethod
    def _decode(data):
        try:
            return data.decode("utf-8")
        except UnicodeDecodeError as e:
            raise ParseError("the body is not valid UTF-8: %s" % e) from None

    def _parse_json(self, data):
        text = self._decode(data)
        try:
            value = json.loads(text)
        except ValueError as e:
            raise ParseError("the body is not valid JSON: %s" % e) from None
        if not isinstance(value, dict):
            raise ValidationError("the body must be a JSON object")
        return value


